// Refinements are local-only: no form submission, analytics, or external storage.
const search=document.querySelector('#product-search'),percent=document.querySelector('#percent-filter');
function refine(){if(!search)return;const type=document.querySelector('[data-filter].active')?.dataset.filter||'all';const text=search.value.trim().toLowerCase();let count=0;document.querySelectorAll('.product-card').forEach(card=>{const show=(type==='all'||card.dataset.type===type)&&(!percent.value||card.dataset.percent===percent.value)&&card.dataset.search.includes(text);card.hidden=!show;if(show)count++;});document.querySelector('#result-count').textContent=`สินค้า ${count} รายการ`;document.querySelector('#no-results').hidden=count!==0;}
search?.addEventListener('input',refine);percent?.addEventListener('change',refine);document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',refine));refine();
const params=new URLSearchParams(location.search);const quote=document.querySelector('.quote-form');if(quote&&params.get('note'))quote.elements.namedItem('note').value=params.get('note');
const requestedQuantity=Number(params.get('quantity'));if(quote&&Number.isInteger(requestedQuantity)&&requestedQuantity>=1&&requestedQuantity<=100000)quote.elements.namedItem('quantity').value=String(requestedQuantity);
if(quote&&/ขอ.*(?:เอกสาร|COA|SDS|Spec)/i.test(params.get('note')||'')){quote.dataset.intent='document';if(!quote.elements.namedItem('product').value)quote.elements.namedItem('product').value='ขอคำแนะนำ';for(const name of ['size','quantity','province']){quote.elements.namedItem(name).required=false;const label=quote.querySelector(`label[for="${name}"]`);label.textContent=label.textContent.replace(' *',' (ถ้ามี)');}quote.querySelector('button[type="submit"]').textContent='จัดเตรียมคำขอเอกสาร';}
const selectedSize=document.querySelector('#detail-size');if(selectedSize&&params.has('size')&&[...selectedSize.options].some(o=>o.value===params.get('size'))){selectedSize.value=params.get('size');selectedSize.dispatchEvent(new Event('change'));}
document.querySelectorAll('.navlinks a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.navlinks').classList.remove('open');document.querySelector('.mobile-toggle')?.setAttribute('aria-expanded','false');}));

if(quote&&params.get('province'))quote.elements.namedItem('province').value=params.get('province').slice(0,80);
